    # action: Username
    page.locator('[data-test="username"]').first.fill(os.environ.get('AIVAR_INVALID_USERNAME', 'not_a_real_user'))
    # action: Password
    page.locator('[data-test="password"]').first.fill(os.environ.get('AIVAR_INVALID_PASSWORD', 'wrong_password_123'))
    # action: Login
    page.locator('[data-test="login-button"]').first.click()
    # assertion: error
    expect(page.locator('[data-test="error-button"]').first).to_be_visible()
